/**
 * Desafio+ — Register Page
 */

import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import toast from 'react-hot-toast';

export default function Register() {
  const { register } = useAuth();
  const navigate = useNavigate();
  const [form, setForm] = useState({ email: '', password: '', username: '', display_name: '' });
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (form.password.length < 8) { toast.error('Senha deve ter pelo menos 8 caracteres'); return; }
    if (!/^[a-z0-9_.]{3,20}$/.test(form.username)) {
      toast.error('Username: 3-20 chars, apenas letras minúsculas, números, . e _');
      return;
    }
    setLoading(true);
    try {
      await register(form.email, form.password, form.username, form.display_name);
      toast.success('Conta criada! Bem-vindo ao Desafio+ 🎉');
      navigate('/feed');
    } catch (err) {
      toast.error(err.response?.data?.error || 'Erro ao criar conta');
    } finally {
      setLoading(false);
    }
  };

  const Field = ({ label, name, type = 'text', placeholder, hint }) => (
    <div>
      <label style={{ display: 'block', marginBottom: '0.4rem', fontSize: '0.9rem', color: 'var(--text-secondary)' }}>
        {label}
      </label>
      <input
        className="input"
        type={type}
        value={form[name]}
        onChange={e => setForm(p => ({ ...p, [name]: e.target.value }))}
        placeholder={placeholder}
        required
      />
      {hint && <p style={{ fontSize: '0.75rem', color: 'var(--text-muted)', marginTop: '0.25rem' }}>{hint}</p>}
    </div>
  );

  return (
    <div style={{
      minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center',
      background: 'var(--bg-primary)', padding: '1rem',
    }}>
      <div style={{ width: '100%', maxWidth: 420 }}>
        <div style={{ textAlign: 'center', marginBottom: '2rem' }}>
          <div style={{ fontSize: '3rem', marginBottom: '0.5rem' }}>🎯</div>
          <h1 className="gradient-text" style={{ fontSize: '2rem', marginBottom: '0.25rem' }}>Desafio+</h1>
          <p style={{ color: 'var(--text-secondary)' }}>Crie sua conta e comece a viver!</p>
        </div>

        <div className="card" style={{ padding: '2rem' }}>
          <h2 style={{ marginBottom: '1.5rem', textAlign: 'center' }}>Criar conta grátis</h2>

          <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
            <Field label="Nome completo" name="display_name" placeholder="Seu nome" />
            <Field
              label="Username"
              name="username"
              placeholder="seunome123"
              hint="3-20 chars, letras minúsculas, números, . e _"
            />
            <Field label="E-mail" name="email" type="email" placeholder="seu@email.com" />
            <Field
              label="Senha"
              name="password"
              type="password"
              placeholder="Mínimo 8 caracteres"
            />

            <button type="submit" className="btn btn-primary" disabled={loading} style={{ padding: '0.75rem', fontSize: '1rem', marginTop: '0.5rem' }}>
              {loading ? <span className="spinner" style={{ width: 20, height: 20 }} /> : 'Criar conta 🚀'}
            </button>
          </form>

          <div style={{ textAlign: 'center', marginTop: '1.5rem', color: 'var(--text-secondary)', fontSize: '0.9rem' }}>
            Já tem conta?{' '}
            <Link to="/login" style={{ color: 'var(--purple-light)', fontWeight: 600 }}>Entrar</Link>
          </div>
        </div>
      </div>
    </div>
  );
}
